<?php
$receipt_requests = isset($requests) && is_array($requests) ? $requests : [];
$invoice_requests_list = isset($invoice_requests) && is_array($invoice_requests) ? $invoice_requests : [];
$delete_requests_list = isset($delete_requests) && is_array($delete_requests) ? $delete_requests : [];
$all_requests = [];
foreach($receipt_requests as $row){$row['_type']='receipt';$row['_status']=strtolower((string)($row['status']??'pending'));$all_requests[]=$row;}
foreach($invoice_requests_list as $row){$row['_type']='invoice';$row['_status']=strtolower((string)($row['status']??'pending'));$all_requests[]=$row;}
foreach($delete_requests_list as $row){$row['_type']='invoice_delete';$row['_status']=strtolower((string)($row['approval_status']??'Pending'));$all_requests[]=$row;}
usort($all_requests,function($a,$b){
    if($a['_type']==='receipt'){$ta=(int)($a['requested_at']??0);}elseif($a['_type']==='invoice_delete'){$ta=strtotime($a['request_created_timestamp']??'1970-01-01');}else{$ta=strtotime($a['created_at']??'1970-01-01');}
    if($b['_type']==='receipt'){$tb=(int)($b['requested_at']??0);}elseif($b['_type']==='invoice_delete'){$tb=strtotime($b['request_created_timestamp']??'1970-01-01');}else{$tb=strtotime($b['created_at']??'1970-01-01');}
    return $tb<=>$ta;
});
$stats=['pending'=>0,'approved'=>0,'closed'=>0,'total'=>count($all_requests)];
foreach($all_requests as $row){$st=$row['_status']??'';if($st==='pending'||$st==='processing')$stats['pending']++;elseif($st==='approved')$stats['approved']++;elseif(in_array($st,['rejected','declined','revoked'],true))$stats['closed']++;}
$csrf_name=$this->security->get_csrf_token_name();
$csrf_hash=$this->security->get_csrf_hash();
?>
<style>
