<div class="mod-approval-workspace">
    <div class="mod-approval-head"><div><p class="mod-approval-eyebrow">Financial Controls</p><h1>Invoice &amp; Receipt Approvals</h1><p>Review invoice deletions and invoice/receipt modifications before they change billing, receipts, credits or ledger balances.</p></div><div class="mod-approval-note"><i class="fa fa-shield-alt"></i> Only super administrators can make approval decisions. Pending rows are locked during financial mutation to prevent duplicate processing.</div></div>
    <div class="mod-stats"><div class="mod-stat pending"><div class="mod-stat-label">Pending / Processing</div><div class="mod-stat-value"><?php echo (int)$stats['pending']; ?></div><div class="mod-stat-hint">Awaiting or currently applying a decision</div></div><div class="mod-stat approved"><div class="mod-stat-label">Approved</div><div class="mod-stat-value"><?php echo (int)$stats['approved']; ?></div><div class="mod-stat-hint">Successfully applied requests</div></div><div class="mod-stat closed"><div class="mod-stat-label">Declined / Rejected</div><div class="mod-stat-value"><?php echo (int)$stats['closed']; ?></div><div class="mod-stat-hint">Includes revoked receipt deletions</div></div><div class="mod-stat"><div class="mod-stat-label">Total Requests</div><div class="mod-stat-value"><?php echo (int)$stats['total']; ?></div><div class="mod-stat-hint">Delete, invoice and receipt requests combined</div></div></div>
    <div class="mod-filters"><div class="mod-filter-field"><label for="typeFilter">Record type</label><select id="typeFilter"><option value="all">All records</option><option value="receipt">Receipt modifications</option><option value="invoice">Invoice modifications</option><option value="invoice_delete">Invoice deletions</option></select></div><div class="mod-filter-field"><label for="statusFilter">Status</label><select id="statusFilter"><option value="all">All statuses</option><option value="pending" selected>Pending</option><option value="processing">Processing</option><option value="approved">Approved</option><option value="rejected">Rejected receipts</option><option value="declined">Declined invoices</option><option value="revoked">Revoked receipts</option></select></div><div class="mod-filter-summary"><span id="visibleCount">0</span> visible request(s)</div></div>
    <div class="mod-bulk" id="bulkActions"><strong><span id="selectedCount">0</span> pending request(s) selected</strong><button type="button" class="btn btn-success" id="bulkApproveBtn"><i class="fa fa-check"></i> Approve Selected</button><button type="button" class="btn btn-danger" id="bulkRejectBtn"><i class="fa fa-times"></i> Reject Selected</button><button type="button" class="btn btn-default" id="clearSelectionBtn">Clear</button></div>
    <div class="mod-list" id="requestsList">
    <?php if(!$all_requests): ?><div class="mod-empty"><i class="fa fa-inbox" style="font-size:28px;margin-bottom:8px;display:block"></i>No finance approval requests found.</div><?php else: foreach($all_requests as $request):
        $type=$request['_type'];
        $is_receipt=$type==='receipt';
        $is_delete=$type==='invoice_delete';
        $status=$request['_status']??'pending';
        $request_id=(int)($request['request_id']??0);
        $student_id=0; $amount=null;
        if($is_receipt){
            $payments=json_decode($request['original_data']??'[]',true);$payments=is_array($payments)?$payments:[];$first=$payments?$payments[0]:[];$student_id=(int)($first['student_id']??0);$amount=array_sum(array_map(function($p){return (float)($p['amount']??0);},$payments));
        } elseif(!$is_delete) {
            $student_id=(int)($request['student_id']??0);
        }
        $student=$student_id?$this->db->where('student_id',$student_id)->get('student')->row_array():[];
        $requester_id=$is_delete?(int)($request['request_issuer_id']??0):(int)($request['requested_by']??0);
        $requester=$requester_id?$this->db->where('admin_id',$requester_id)->get('admin')->row_array():[];
        $reason=$is_delete?($request['request_description']??''):($is_receipt?($request['reason']??''):($request['request_reason']??''));
        if($is_delete){$date_value=!empty($request['request_created_timestamp'])?date('d M Y, H:i',strtotime($request['request_created_timestamp'])):'—';}
        elseif($is_receipt){$date_value=!empty($request['requested_at'])?date('d M Y, H:i',(int)$request['requested_at']):'—';}
        else{$date_value=!empty($request['created_at'])?date('d M Y, H:i',strtotime($request['created_at'])):'—';}
        $record_code=$is_delete?($request['request_ids']??''):($is_receipt?($request['receipt_code']??''):($request['invoice_code']??''));
        $request_type=$is_delete?'delete':($request['request_type']??'edit');
        $rejection=$is_receipt?($request['rejection_reason']??''):'';
        $type_label=$is_delete?'Invoice Delete':($is_receipt?'Receipt':'Invoice');
        $type_icon=$is_receipt?'receipt':'file-invoice';
    ?>
        <article class="mod-card <?php echo html_escape($status); ?>" data-type="<?php echo $type; ?>" data-status="<?php echo html_escape($status); ?>" data-request-id="<?php echo $request_id; ?>" data-is-receipt="<?php echo $is_receipt?'1':'0'; ?>">
            <div class="mod-card-head"><div class="mod-card-id"><?php if($status==='pending' && !$is_delete): ?><input type="checkbox" class="mod-checkbox request-checkbox" aria-label="Select request <?php echo $request_id; ?>"><?php endif; ?><span class="mod-type"><i class="fa fa-<?php echo $type_icon; ?>"></i>&nbsp; <?php echo html_escape($type_label); ?></span><span class="mod-action"><?php echo html_escape(ucfirst($request_type)); ?></span><span style="color:#64748b;font-size:12px;font-weight:800">#<?php echo $request_id; ?></span></div><span class="mod-status <?php echo html_escape($status); ?>"><?php echo html_escape(ucfirst(str_replace('_',' ',$status))); ?></span></div>
            <div class="mod-details">
                <?php if(!$is_delete): ?><div><div class="mod-detail-label">Student</div><div class="mod-detail-value"><?php echo html_escape($student['name']??'N/A'); ?></div></div><?php endif; ?>
                <div><div class="mod-detail-label"><?php echo $is_delete?'Invoice code(s)':($is_receipt?'Receipt No.':'Invoice No.'); ?></div><div class="mod-detail-value"><?php echo html_escape((string)$record_code); ?></div></div>
                <div><div class="mod-detail-label">Requested By</div><div class="mod-detail-value"><?php echo html_escape($requester['name']??'N/A'); ?></div></div>
                <div><div class="mod-detail-label">Requested</div><div class="mod-detail-value"><?php echo html_escape($date_value); ?></div></div>
                <?php if($amount!==null): ?><div><div class="mod-detail-label">Original Receipt Total</div><div class="mod-detail-value">₵ <?php echo number_format($amount,2); ?></div></div><?php endif; ?>
            </div>
            <?php if(trim((string)$reason)!==''): ?><div class="mod-reason"><strong><?php echo $is_delete?'Request':'Reason'; ?>:</strong> <?php echo nl2br(html_escape($reason)); ?></div><?php endif; ?>
            <?php if(trim((string)$rejection)!==''): ?><div class="mod-rejection"><strong>Rejection reason:</strong> <?php echo nl2br(html_escape($rejection)); ?></div><?php endif; ?>
            <div class="mod-card-actions">
                <?php if(!$is_delete): ?><button type="button" class="btn btn-primary js-view-request" data-id="<?php echo $request_id; ?>" data-type="<?php echo $type; ?>"><i class="fa fa-eye"></i> View Details</button><?php endif; ?>
                <?php if($status==='pending' && $is_delete): ?>
                    <button type="button" class="btn btn-success js-decide-delete" data-id="<?php echo $request_id; ?>" data-status="Approved"><i class="fa fa-check"></i> Approve Delete</button>
                    <button type="button" class="btn btn-danger js-decide-delete" data-id="<?php echo $request_id; ?>" data-status="Declined"><i class="fa fa-times"></i> Decline</button>
                <?php elseif($status==='pending'): ?>
                    <button type="button" class="btn btn-success js-approve-request" data-id="<?php echo $request_id; ?>" data-type="<?php echo $type; ?>"><i class="fa fa-check"></i> Approve</button>
                    <button type="button" class="btn btn-danger js-reject-request" data-id="<?php echo $request_id; ?>" data-type="<?php echo $type; ?>"><i class="fa fa-times"></i> <?php echo $is_receipt?'Reject':'Decline'; ?></button>
                <?php elseif($is_receipt && $status==='approved' && $request_type==='delete'): ?>
                    <button type="button" class="btn btn-danger js-revoke-receipt" data-id="<?php echo $request_id; ?>"><i class="fa fa-undo"></i> Revoke &amp; Restore Receipt</button>
                <?php endif; ?>
            </div>
        </article>
    <?php endforeach; endif; ?>
    </div>
</div>
<script>
var modBusy=false,modCsrfName=<?php echo json_encode($csrf_name); ?>,modCsrfHash=<?php echo json_encode($csrf_hash); ?>;
function modPost(data){data=data||{};data[modCsrfName]=modCsrfHash;return data;}
function modError(xhr,fallback){var msg=fallback||'Operation failed';try{var r=JSON.parse(xhr.responseText);if(r.message)msg=r.message;}catch(e){}showAjaxModal_alert(msg,'error');}
function filterRequests(){var type=$('#typeFilter').val(),status=$('#statusFilter').val(),visible=0;$('.mod-card').each(function(){var show=(type==='all'||$(this).data('type')===type)&&(status==='all'||$(this).data('status')===status);$(this).toggle(show);if(show)visible++;});$('#visibleCount').text(visible);$('.request-checkbox:hidden').prop('checked',false);updateBulkActions();}
function updateBulkActions(){var count=$('.request-checkbox:checked').length;$('#selectedCount').text(count);$('#bulkActions').toggleClass('active',count>0);}
function clearSelection(){$('.request-checkbox').prop('checked',false);updateBulkActions();}
function selectedRequests(){var rows=[];$('.request-checkbox:checked').each(function(){var card=$(this).closest('.mod-card');rows.push({id:parseInt(card.data('request-id'),10),is_receipt:card.data('is-receipt')==1});});return rows;}
function reloadApprovals(){location.reload();}
$(function(){$('#typeFilter,#statusFilter').on('change',filterRequests);$(document).on('change','.request-checkbox',updateBulkActions);$('#clearSelectionBtn').on('click',clearSelection);$('#bulkApproveBtn').on('click',function(){bulkModification('approve');});$('#bulkRejectBtn').on('click',function(){bulkModification('reject');});$(document).on('click','.js-view-request',function(){viewRequestDetails($(this).data('id'),$(this).data('type'));});$(document).on('click','.js-approve-request',function(){approveModification($(this).data('id'),$(this).data('type'));});$(document).on('click','.js-reject-request',function(){rejectModification($(this).data('id'),$(this).data('type'));});$(document).on('click','.js-decide-delete',function(){decideInvoiceDelete($(this).data('id'),$(this).data('status'));});$(document).on('click','.js-revoke-receipt',function(){revokeReceipt($(this).data('id'));});filterRequests();});
function viewRequestDetails(id,type){if(type==='receipt')loadModalContent('detailsModal','<?php echo site_url('admin/receipt_modification_details/'); ?>'+id,'<i class="fa fa-receipt"></i> Receipt Modification Details');else loadModalContent('detailsModal','<?php echo site_url('admin/invoice_modification_details/'); ?>'+id,'<i class="fa fa-file-invoice"></i> Invoice Modification Details');}
function approveModification(id,type){if(modBusy)return;showConfirmModal('Confirm Approval','Approve this '+type+' modification request? Financial changes will be applied immediately.',function(){if(modBusy)return;modBusy=true;showAjaxModal_alert('Processing…','loading');var url=type==='receipt'?'<?php echo site_url('admin/approve_receipt_modification'); ?>':'<?php echo site_url('admin/review_invoice_modification/'); ?>'+id+'/approve';var data=modPost(type==='receipt'?{request_id:id}:{});$.ajax({url:url,type:'POST',data:data,dataType:'json'}).done(function(r){showAjaxModal_alert(r.message,r.status==='success'?'success':'error');if(r.status==='success')setTimeout(reloadApprovals,900);}).fail(function(xhr){modError(xhr,'Approval failed.');}).always(function(){modBusy=false;});},'Approve','success');}
function rejectModification(id,type){if(modBusy)return;if(type==='receipt'){showConfirmModal('Confirm Rejection','<div style="margin-bottom:8px">Enter a rejection reason:</div><textarea id="receiptRejectReason" class="form-control" rows="3" style="font-size:15px"></textarea>',function(){var reason=$('#receiptRejectReason').val().trim();if(!reason){showAjaxModal_alert('Rejection reason is required.','warning');return;}sendReject(id,type,reason);},'Reject','danger');}else{showConfirmModal('Confirm Decline','Decline this invoice modification request?',function(){sendReject(id,type,'');},'Decline','danger');}}
function decideInvoiceDelete(id,status){if(modBusy)return;var approving=status==='Approved';showConfirmModal(approving?'Approve Invoice Deletion':'Decline Invoice Deletion',approving?'Approve this invoice deletion request? The requester will then be allowed to move only the approved invoice(s) to trash.':'Decline this invoice deletion request?',function(){if(modBusy)return;modBusy=true;showAjaxModal_alert('Processing…','loading');$.ajax({url:'<?php echo site_url('admin/manageRequestApproval/manage/'); ?>'+id+'/'+status,type:'POST',data:modPost({}),dataType:'json'}).done(function(r){showAjaxModal_alert(r.message,r.status==='success'?'success':'error');if(r.status==='success')setTimeout(reloadApprovals,900);}).fail(function(xhr){modError(xhr,'Invoice delete decision failed.');}).always(function(){modBusy=false;});},approving?'Approve':'Decline',approving?'success':'danger');}
function sendReject(id,type,reason){if(modBusy)return;modBusy=true;showAjaxModal_alert('Processing…','loading');var url=type==='receipt'?'<?php echo site_url('admin/reject_receipt_modification'); ?>':'<?php echo site_url('admin/review_invoice_modification/'); ?>'+id+'/decline';var data=modPost(type==='receipt'?{request_id:id,reason:reason}:{});$.ajax({url:url,type:'POST',data:data,dataType:'json'}).done(function(r){showAjaxModal_alert(r.message,r.status==='success'?'success':'error');if(r.status==='success')setTimeout(reloadApprovals,900);}).fail(function(xhr){modError(xhr,'Decision failed.');}).always(function(){modBusy=false;});}
function revokeReceipt(id){if(modBusy)return;showConfirmModal('Confirm Receipt Restore','Restore the original deleted receipt and its invoice balances? This is available only for approved receipt-deletion requests with an intact original snapshot.',function(){modBusy=true;showAjaxModal_alert('Restoring…','loading');$.ajax({url:'<?php echo site_url('admin/revoke_receipt_approval'); ?>',type:'POST',data:modPost({request_id:id}),dataType:'json'}).done(function(r){showAjaxModal_alert(r.message,r.status==='success'?'success':'error');if(r.status==='success')setTimeout(reloadApprovals,900);}).fail(function(xhr){modError(xhr,'Receipt restore failed.');}).always(function(){modBusy=false;});},'Revoke & Restore','danger');}
function bulkModification(action){var rows=selectedRequests();if(!rows.length){showAjaxModal_alert('Select at least one pending request.','warning');return;}if(modBusy)return;showConfirmModal(action==='approve'?'Confirm Bulk Approval':'Confirm Bulk Rejection',(action==='approve'?'Approve ':'Reject / decline ')+rows.length+' pending request(s)?',function(){if(modBusy)return;modBusy=true;showAjaxModal_alert('Processing…','loading');$.ajax({url:action==='approve'?'<?php echo site_url('admin/bulk_approve_modifications'); ?>':'<?php echo site_url('admin/bulk_reject_modifications'); ?>',type:'POST',data:modPost({requests:JSON.stringify(rows)}),dataType:'json'}).done(function(r){showAjaxModal_alert(r.message,r.status==='success'?'success':'error');setTimeout(reloadApprovals,900);}).fail(function(xhr){modError(xhr,'Bulk decision failed.');}).always(function(){modBusy=false;});},action==='approve'?'Approve':'Reject','danger');}
</script>
